                .filter(customer -> matches(customer, filter))
                .sorted(comparatorFor(sorts))
                .skip(offset)
                .limit(limit)
                .toList();
        queryLog.recordPage(offset, limit, page.size());
        return page;
    }

    /** Returns the number of customers matching {@code filter}. */
    public int count(CustomerFilter filter) {
        int total = (int) customers.stream().filter(customer -> matches(customer, filter)).count();
        queryLog.recordCount(total);
        return total;
    }

    private static boolean matches(Customer customer, CustomerFilter filter) {
        if (!filter.statuses().isEmpty() && !filter.statuses().contains(customer.status())) {
            return false;
        }
        String trimmedName = filter.name().trim();
        if (trimmedName.isEmpty()) {
            return true;
        }
        String normalizedFirst = normalize(customer.firstName());
        String normalizedLast = normalize(customer.lastName());
        for (String term : trimmedName.split("\\s+")) {
            String normalizedTerm = normalize(term);
            if (!normalizedFirst.contains(normalizedTerm) && !normalizedLast.contains(normalizedTerm)) {
                return false;
            }
        }
        return true;
    }

    /** Lower-cases and strips diacritics, so filtering ignores case and accents. */
    private static String normalize(String s) {
        String decomposed = Normalizer.normalize(s, Normalizer.Form.NFD);
        return decomposed.replaceAll("\\p{M}", "").toLowerCase(Locale.ROOT);
